mapper.select:
SELECT t.id, t.part_code AS partCode, t.part_name AS partName, t.parent_id AS parentId, t.status, CASE WHEN COUNT(c.id) > 0 THEN 1 ELSE 0 END AS hasChildren FROM his_basedata_body_part t LEFT JOIN his_basedata_body_part c ON c.parent_id = t.id
AND (t.part_code LIKE CONCAT('%', #{keyword}, '%') OR t.part_name LIKE CONCAT('%', #{keyword}, '%'))
AND t.parent_id IS NULL
AND t.parent_id = #{parentId}
AND t.status = #{status}
GROUP BY t.id, t.part_code, t.part_name, t.parent_id, t.status ORDER BY t.sort_order ASC
